 "content": "def transform(grid):
    """Expand each isolated marker into a centered copy of the horizontal motif."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find the longest contiguous horizontal run of non-background cells;
    # this run is the motif to copy.
    best = None
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            run = (c - start, r, start, row[start:c])
            if best is None or run[0] > best[0]:
                best = run
    length, motif_row, motif_start, motif = best
    motif_cells = {(motif_row, c) for c in range(motif_start, motif_start + length)}

    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in motif_cells]
    for r, c in markers:
        out[r][c] = bg
    offset = length // 2
    for r, c in markers:
        start = c - offset
        for i, value in enumerate(motif):
            x = start + i
            if 0 <= x < w:
                out[r][x] = value
    return out
